/*!
 * shipnote-widget — vanilla, dependency-free, embeddable changelog feed.
 * Generated by shipnote. Drop a script tag with `data-feed` pointing at
 * a JSON Feed 1.1 file produced by `shipnote site`.
 *
 * <div id="shipnote"></div>
 * <script src="https://your-site/changelog/assets/widget.js"
 *         data-feed="https://your-site/changelog/feed.json"
 *         data-mount="#shipnote"
 *         data-limit="5"
 *         data-audience="customer"></script>
 */
(function () {
 'use strict';

 var current = document.currentScript;
 if (!current) return;

 var feedURL = current.getAttribute('data-feed');
 var mount = current.getAttribute('data-mount') || '#shipnote';
 var limit = parseInt(current.getAttribute('data-limit') || '5', 10);
 var audience = current.getAttribute('data-audience') || 'customer';

 if (!feedURL) {
  console.warn('[shipnote] data-feed is required');
  return;
 }

 var target = typeof mount === 'string' ? document.querySelector(mount) : mount;
 if (!target) {
  console.warn('[shipnote] mount element not found:', mount);
  return;
 }

 // Inject minimal styles once.
 if (!document.getElementById('shipnote-widget-style')) {
  var stylesheet = current.getAttribute('data-stylesheet');
  if (stylesheet) {
   var link = document.createElement('link');
   link.id = 'shipnote-widget-style';
   link.rel = 'stylesheet';
   link.href = stylesheet;
   document.head.appendChild(link);
  } else {
   var style = document.createElement('style');
   style.id = 'shipnote-widget-style';
   style.textContent = WIDGET_STYLES();
   document.head.appendChild(style);
  }
 }

 target.classList.add('shipnote-widget');
 target.innerHTML = '<div class="shipnote-loading">Loading changelog…</div>';

 fetch(feedURL, { credentials: 'omit' })
  .then(function (r) {
   if (!r.ok) throw new Error('HTTP ' + r.status);
   return r.json();
  })
  .then(function (feed) {
   render(target, feed, { limit: limit, audience: audience });
  })
  .catch(function (err) {
   target.innerHTML =
    '<div class="shipnote-error">Could not load changelog: ' +
    escapeHTML(String(err)) +
    '</div>';
  });

 function render(el, feed, opts) {
  var items = (feed.items || []).slice(0, opts.limit);
  if (!items.length) {
   el.innerHTML = '<div class="shipnote-empty">No releases yet.</div>';
   return;
  }
  var html = '<header class="shipnote-head">';
  html += '<h3>' + escapeHTML(feed.title || 'Changelog') + '</h3>';
  if (feed.home_page_url) {
   html +=
    '<a class="shipnote-all" href="' +
    feed.home_page_url +
    '">View all releases</a>';
  }
  html += '</header>';
  html += '<ol class="shipnote-list">';
  items.forEach(function (it) {
   var ext = it._shipnote || {};
   var summary =
    (ext.aiSummaries && summaryFor(ext.aiSummaries, opts.audience)) ||
    it.summary ||
    firstPara(it.content_text || '');
   var pills = '';
   var counts = ext.counts || {};
   if (ext.breakingChanges)
    pills += pill('breaking', ext.breakingChanges + ' breaking');
   if (counts.feat) pills += pill('feat', counts.feat + ' added');
   if (counts.fix) pills += pill('fix', counts.fix + ' fixed');
   html +=
    '<li class="shipnote-item">' +
    '<a class="shipnote-title" href="' +
    (it.url || '#') +
    '"><span class="shipnote-tag">' +
    escapeHTML(it.title) +
    '</span>' +
    '<time datetime="' +
    (it.date_published || '') +
    '">' +
    formatDate(it.date_published) +
    '</time>' +
    '</a>' +
    '<div class="shipnote-pills">' +
    pills +
    '</div>' +
    (summary
     ? '<p class="shipnote-summary">' + escapeHTML(summary) + '</p>'
     : '') +
    '</li>';
  });
  html += '</ol>';
  el.innerHTML = html;
 }

 function summaryFor(ai, audience) {
  var entry = ai && ai[audience];
  return entry && entry.text ? entry.text : '';
 }

 function pill(kind, text) {
  return (
   '<span class="shipnote-pill shipnote-pill-' +
   kind +
   '">' +
   escapeHTML(text) +
   '</span>'
  );
 }

 function firstPara(s) {
  var idx = s.indexOf('\n\n');
  return idx === -1 ? s : s.slice(0, idx);
 }

 function formatDate(s) {
  if (!s) return '';
  try {
   var d = new Date(s);
   if (isNaN(d.getTime())) return s;
   return d.toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
   });
  } catch (e) {
   return s;
  }
 }

 function escapeHTML(s) {
  return String(s)
   .replace(/&/g, '&amp;')
   .replace(/</g, '&lt;')
   .replace(/>/g, '&gt;')
   .replace(/"/g, '&quot;')
   .replace(/'/g, '&#39;');
 }

 function WIDGET_STYLES() {
  return [
   ".shipnote-widget{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;color:inherit;border:1px solid var(--shipnote-border,#e5e7eb);border-radius:8px;padding:1rem 1.25rem;max-width:520px}",
   '.shipnote-widget .shipnote-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:.75rem}',
   '.shipnote-widget h3{margin:0;font-size:.95rem;text-transform:uppercase;letter-spacing:.05em;color:var(--shipnote-muted,#6b7280)}',
   '.shipnote-widget .shipnote-all{font-size:.8rem;color:var(--shipnote-accent,#2563eb);text-decoration:none}',
   '.shipnote-widget .shipnote-all:hover{text-decoration:underline}',
   '.shipnote-widget ol{list-style:none;padding:0;margin:0}',
   '.shipnote-widget li{padding:.6rem 0;border-bottom:1px solid var(--shipnote-border,#e5e7eb)}',
   '.shipnote-widget li:last-child{border-bottom:0}',
   '.shipnote-widget .shipnote-title{display:flex;justify-content:space-between;align-items:baseline;text-decoration:none;color:inherit}',
   '.shipnote-widget .shipnote-title:hover .shipnote-tag{text-decoration:underline}',
   '.shipnote-widget .shipnote-tag{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-weight:600}',
   '.shipnote-widget time{font-size:.8rem;color:var(--shipnote-muted,#6b7280)}',
   '.shipnote-widget .shipnote-pills{margin:.25rem 0}',
   '.shipnote-widget .shipnote-pill{display:inline-block;font-size:.7rem;font-weight:600;padding:.05rem .45rem;border-radius:999px;border:1px solid currentColor;margin-right:.35rem}',
   '.shipnote-widget .shipnote-pill-feat{color:#059669}',
   '.shipnote-widget .shipnote-pill-fix{color:#d97706}',
   '.shipnote-widget .shipnote-pill-breaking{color:#dc2626}',
   '.shipnote-widget .shipnote-summary{margin:.25rem 0 0;font-size:.9rem;color:var(--shipnote-muted,#4b5563)}',
   '.shipnote-widget .shipnote-loading,.shipnote-widget .shipnote-empty,.shipnote-widget .shipnote-error{padding:.5rem 0;color:var(--shipnote-muted,#6b7280);font-size:.9rem}',
   '.shipnote-widget .shipnote-error{color:#dc2626}',
  ].join('');
 }
})();
